import torch


def run(input_gates, hidden_gates, cx, input_bias, hidden_bias):
    gates = input_gates + hidden_gates
    if input_bias is not None:
        gates = gates + input_bias
    if hidden_bias is not None:
        gates = gates + hidden_bias
    i, f, g, o = gates.chunk(4, dim=-1)
    i = torch.sigmoid(i)
    f = torch.sigmoid(f)
    g = torch.tanh(g)
    o = torch.sigmoid(o)
    cy = f * cx + i * g
    hy = o * torch.tanh(cy)
    return hy, cy, gates


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    if len(ref_outputs) < 2 or len(sol_outputs) < 2:
        return {"passed": False, "message": "expected hy and cy", "metrics": {}}
    dtype = sol_outputs[0].dtype
    rtol = {
        torch.float16: 1e-3,
        torch.bfloat16: 1.6e-2,
        torch.float32: 1.3e-6,
    }.get(dtype, 1e-6)
    atol = 1e-2 if dtype == torch.bfloat16 else (1.5e-3 if dtype == torch.float16 else 1e-4)
    for name, ref, sol in zip(("hy", "cy"), ref_outputs[:2], sol_outputs[:2]):
        if ref.shape != sol.shape or not torch.allclose(ref, sol, rtol=rtol, atol=atol):
            return {"passed": False, "message": f"{name} mismatch", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
